def sha(data):return hashlib.sha256(data).hexdigest()
def produce(sources):
    if set(sources)!=set(FILES):raise ValueError("exact canonical7 required")
    for name in FILES:
        if sha(sources[name])!=INPUT_SHA[name] or b"\r" in sources[name]:raise ValueError("canonical input differs: "+name)
    result=dict(sources);proof={"files":{},"canonical7_exact":True,"scope":"explicit finite shipping class; protocol change"}
    for name in FILES:
        original=sources[name];selected=[]
        for edit in EDITS:
            if edit["file"]!=name:continue
            if original.count(edit["old"])!=1:raise ValueError("sole old literal differs")
            selected.append((original.index(edit["old"]),edit))
        selected.sort(key=lambda row:row[0]);chunks=[];cursor=0;at_new=0;spans=[];gaps=[]
        for at,edit in selected:
            if at<cursor:raise ValueError("overlapping edits")
            gap=original[cursor:at];chunks.extend((gap,edit["new"]))
            gaps.append({"old_offset":cursor,"new_offset":at_new,"bytes":len(gap),"sha256":sha(gap)})
            at_new+=len(gap);spans.append({"old_offset":at,"new_offset":at_new,"old":edit["old"].decode(),"new":edit["new"].decode(),"role":edit["role"]})
            at_new+=len(edit["new"]);cursor=at+len(edit["old"])
        gap=original[cursor:];chunks.append(gap);gaps.append({"old_offset":cursor,"new_offset":at_new,"bytes":len(gap),"sha256":sha(gap)})
        changed=b"".join(chunks);inverse=changed
        for span in reversed(spans):
            at=span["new_offset"];old=span["old"].encode();new=span["new"].encode()
            if inverse[at:at+len(new)]!=new:raise ValueError("inverse span differs")
            inverse=inverse[:at]+old+inverse[at+len(new):]
        if inverse!=original:raise ValueError("full inverse differs")
        for gap in gaps:
            if original[gap["old_offset"]:gap["old_offset"]+gap["bytes"]]!=changed[gap["new_offset"]:gap["new_offset"]+gap["bytes"]]:raise ValueError("protected complement differs")
        result[name]=changed;proof["files"][name]={"input":{"bytes":len(original),"sha256":sha(original)},"output":{"bytes":len(changed),"sha256":sha(changed)},"raw_delta":len(changed)-len(original),"spans":spans,"gaps":gaps,"full_inverse":True}
    proof["changed_files"]=[name for name in FILES if sources[name]!=result[name]]
    proof["rust_raw_delta"]=sum(len(result[n])-len(sources[n]) for n in FILES if n.endswith(".rs"))
    return result,proof
